class Solution {
public:
        int removeDuplicates(vector<int>& nums) {
            if(nums.size() <= 1){
                return (int)nums.size();
            }
            int slow = 0;
            for (int i = 1; i < nums.size(); i++) {
                if(nums[slow] != nums[i]){
                    nums[++slow] = nums[i];
                }
                 // equal and compare next value.
            }
            return slow + 1;
        }
};

