void trimLeftTrailingSpaces(string &input) {
    input.erase(input.begin(),find_if(input.begin(), input.end(), [](int ch){
        return !isspace(ch);
    }));
}

void trimRightTrailingSpaces(string &input) {
    input.erase(find_if(input.rbegin(), input.rend(), [](int ch){
        return !isspace(ch);
    }).base(),input.end());
}

