string vectorToString(vector<int> &list,int length = -1){
    if(length == -1){
        length = static_cast<int>(list.size());
    }
    if(length == 0){
        return "[]";
    }

    string result;
    for (int &item : list) {
        result += to_string(item) + ",";
    }

    return "[" + result.substr(0, result.length() - 2) + "]";
}

